18	const (
19		pendingV2FullGenerationPublicationVersion = 1
20		pendingV2FullGenerationPublicationDirName = "entire-v2-rotations"
21		pendingV2FullGenerationPublicationFile    = "pending.json"
22		pendingV2FullGenerationPublicationLock    = "pending.lock"
23		pendingV2FullGenerationPublicationLockTTL = 5 * time.Second
24	)
25	
26	type PendingV2FullGenerationPublication struct {
27		ArchiveRefName    string `json:"archive_ref_name"`
28		ArchiveCommitHash string `json:"archive_commit_hash"`
29		// PreviousFullCurrentHash and ResetFullCurrentRootHash are set when the
30		// archive publication came from a local /full/current rotation.
31		PreviousFullCurrentHash  string    `json:"previous_full_current_hash,omitempty"`
32		ResetFullCurrentRootHash string    `json:"reset_full_current_root_hash,omitempty"`
33		QueuedAt                 time.Time `json:"queued_at"`
34	}
35	
36	type pendingV2FullGenerationPublicationState struct {
37		Version      int                                  `json:"version"`
38		Publications []PendingV2FullGenerationPublication `json:"publications"`
39	}
40	
41	func (s *V2GitStore) AppendPendingFullGenerationPublication(ctx context.Context, publication PendingV2FullGenerationPublication) error {
42		return s.AppendPendingFullGenerationPublications(ctx, []PendingV2FullGenerationPublication{publication})
43	}
44	
45	func (s *V2GitStore) AppendPendingFullGenerationPublications(ctx context.Context, publications []PendingV2FullGenerationPublication) error {
46		if len(publications) == 0 {
47			return nil
48		}
49		return s.withPendingFullGenerationPublicationLock(ctx, func() error {
50			state, err := s.readPendingFullGenerationPublicationState(ctx)
51			if err != nil {
52				return err
53			}
54			state.Version = pendingV2FullGenerationPublicationVersion
55			state.Publications = append(state.Publications, publications...)
56			return s.writePendingFullGenerationPublicationState(ctx, state)
57		})
58	}
59	
60	func (s *V2GitStore) ReadPendingFullGenerationPublications(ctx context.Context) ([]PendingV2FullGenerationPublication, error) {
61		state, err := s.readPendingFullGenerationPublicationState(ctx)
62		if err != nil {
63			return nil, err
64		}
65		return state.Publications, nil
66	}
67	
68	func (s *V2GitStore) ClearPendingFullGenerationPublications(ctx context.Context) error {
69		return s.withPendingFullGenerationPublicationLock(ctx, func() error {
70			return s.removePendingFullGenerationPublicationFile(ctx)
71		})
72	}
73	
74	func (s *V2GitStore) RemovePendingFullGenerationPublications(ctx context.Context, publications []PendingV2FullGenerationPublication) error {
75		if len(publications) == 0 {
76			return nil
77		}
78		return s.withPendingFullGenerationPublicationLock(ctx, func() error {
79			state, err := s.readPendingFullGenerationPublicationState(ctx)
80			if err != nil {
81				return err
82			}
83			state.Publications = removePendingFullGenerationPublications(state.Publications, publications)
84			if len(state.Publications) == 0 {
85				return s.removePendingFullGenerationPublicationFile(ctx)
86			}
87			state.Version = pendingV2FullGenerationPublicationVersion
88			return s.writePendingFullGenerationPublicationState(ctx, state)
89		})
90	}
91	
92	func removePendingFullGenerationPublications(current, remove []PendingV2FullGenerationPublication) []PendingV2FullGenerationPublication {
93		removeCounts := make(map[PendingV2FullGenerationPublication]int, len(remove))
94		for _, publication := range remove {
95			removeCounts[comparablePendingFullGenerationPublication(publication)]++
96		}
97	
98		remaining := make([]PendingV2FullGenerationPublication, 0, len(current))
99		for _, publication := range current {
100			key := comparablePendingFullGenerationPublication(publication)
101			if removeCounts[key] > 0 {
102				removeCounts[key]--
103				continue
104			}
105			remaining = append(remaining, publication)
106		}
107		return remaining
108	}
109	
110	func comparablePendingFullGenerationPublication(publication PendingV2FullGenerationPublication) PendingV2FullGenerationPublication {
111		publication.QueuedAt = publication.QueuedAt.Round(0).UTC()
112		return publication
113	}
114	
115	func (s *V2GitStore) removePendingFullGenerationPublicationFile(ctx context.Context) error {
116		path, err := s.pendingFullGenerationPublicationFilePath(ctx)
117		if err != nil {
118			return err
119		}
120		if err := os.Remove(path); err != nil && !os.IsNotExist(err) {
121			return fmt.Errorf("remove pending v2 full generation publications: %w", err)
122		}
123		return nil
124	}
125	
126	func (s *V2GitStore) withPendingFullGenerationPublicationLock(ctx context.Context, fn func() error) (err error) {
127		lockPath, err := s.pendingFullGenerationPublicationLockPath(ctx)
128		if err != nil {
129			return err
130		}
131		if err := os.MkdirAll(filepath.Dir(lockPath), 0o750); err != nil {
132			return fmt.Errorf("create pending v2 full generation publication lock dir: %w", err)
133		}
134		if err := lockfile.WithTimeout(ctx, lockPath, pendingV2FullGenerationPublicationLockTTL, fn); err != nil {
135			return fmt.Errorf("pending v2 full generation publication lock: %w", err)
136		}
137		return nil
138	}
139	
140	func (s *V2GitStore) readPendingFullGenerationPublicationState(ctx context.Context) (pendingV2FullGenerationPublicationState, error) {
141		path, err := s.pendingFullGenerationPublicationFilePath(ctx)
142		if err != nil {
143			return pendingV2FullGenerationPublicationState{}, err
144		}
145		data, err := os.ReadFile(path) //nolint:gosec // path is under git common dir
146		if os.IsNotExist(err) {
147			return pendingV2FullGenerationPublicationState{Version: pendingV2FullGenerationPublicationVersion}, nil
148		}
149		if err != nil {
150			return pendingV2FullGenerationPublicationState{}, fmt.Errorf("read pending v2 full generation publications: %w", err)
151		}
152	
153		var state pendingV2FullGenerationPublicationState
154		if err := json.Unmarshal(data, &state); err != nil {
155			return pendingV2FullGenerationPublicationState{}, fmt.Errorf("parse pending v2 full generation publications: %w", err)
156		}
157		if state.Version != pendingV2FullGenerationPublicationVersion {
158			return pendingV2FullGenerationPublicationState{}, fmt.Errorf("unsupported pending v2 full generation publication version %d", state.Version)
159		}
160		return state, nil
161	}
162	
163	func (s *V2GitStore) writePendingFullGenerationPublicationState(ctx context.Context, state pendingV2FullGenerationPublicationState) error {
164		path, err := s.pendingFullGenerationPublicationFilePath(ctx)
165		if err != nil {
166			return err
167		}
168		if err := os.MkdirAll(filepath.Dir(path), 0o750); err != nil {
169			return fmt.Errorf("create pending v2 full generation publication dir: %w", err)
170		}
171	
172		data, err := jsonutil.MarshalIndentWithNewline(state, "", "  ")
173		if err != nil {
174			return fmt.Errorf("marshal pending v2 full generation publications: %w", err)
175		}
176	
177		tmpFile, err := os.CreateTemp(filepath.Dir(path), pendingV2FullGenerationPublicationFile+".*.tmp")
178		if err != nil {
179			return fmt.Errorf("create pending v2 full generation publication temp file: %w", err)
180		}
181		tmpName := tmpFile.Name()
182		removeTmp := true
183		defer func() {
184			if removeTmp {
185				_ = os.Remove(tmpName)
186			}
187		}()
188	
189		if _, err := tmpFile.Write(data); err != nil {
190			_ = tmpFile.Close()
191			return fmt.Errorf("write pending v2 full generation publications: %w", err)
192		}
193		if err := tmpFile.Close(); err != nil {
194			return fmt.Errorf("close pending v2 full generation publications: %w", err)
195		}
196		if err := os.Rename(tmpName, path); err != nil {
197			return fmt.Errorf("replace pending v2 full generation publications: %w", err)
198		}
199		removeTmp = false
200		return nil
201	}
202	
203	func (s *V2GitStore) pendingFullGenerationPublicationFilePath(ctx context.Context) (string, error) {
204		commonDir, err := s.gitCommonDir(ctx)
205		if err != nil {
206			return "", err
207		}
208		return filepath.Join(commonDir, pendingV2FullGenerationPublicationDirName, pendingV2FullGenerationPublicationFile), nil
209	}
210	
211	func (s *V2GitStore) pendingFullGenerationPublicationLockPath(ctx context.Context) (string, error) {
212		commonDir, err := s.gitCommonDir(ctx)
213		if err != nil {
214			return "", err
215		}
216		return filepath.Join(commonDir, pendingV2FullGenerationPublicationDirName, pendingV2FullGenerationPublicationLock), nil
217	}
218	
219	func (s *V2GitStore) gitCommonDir(ctx context.Context) (string, error) {
220		worktree, err := s.repo.Worktree()
221		if err != nil {
222			return "", fmt.Errorf("open worktree for pending v2 full generation publications: %w", err)
223		}
224		root := worktree.Filesystem.Root()
225		if root == "" {
226			return "", errors.New("resolve worktree root for pending v2 full generation publications")
227		}
228	
229		cmd := exec.CommandContext(ctx, "git", "-C", root, "rev-parse", "--git-common-dir")
230		output, err := cmd.Output()
231		if err != nil {
232			return "", fmt.Errorf("resolve git common dir for pending v2 full generation publications: %w", err)
233		}
234		commonDir := strings.TrimSpace(string(output))
235		if commonDir == "" {
236			return "", errors.New("resolve git common dir for pending v2 full generation publications: empty output")
237		}
238		if !filepath.IsAbs(commonDir) {
239			commonDir = filepath.Join(root, commonDir)
240		}
241		return filepath.Clean(commonDir), nil
242	}
