27	// tryPushRef attempts to push a custom ref using an explicit refspec.
28	func tryPushRef(ctx context.Context, target string, refName plumbing.ReferenceName) error {
29		ctx, cancel := context.WithTimeout(ctx, 2*time.Minute)
30		defer cancel()
31	
32		refSpec := fmt.Sprintf("%s:%s", refName, refName)
33		result, err := remote.Push(ctx, target, refSpec)
34		outputStr := result.Output
35		if err != nil {
36			return classifyPushFailure(ctx, outputStr, err)
37		}
38	
39		return nil
40	}
41	
42	type v2RefPushResult struct {
43		refName plumbing.ReferenceName
44		result  pushResult
45		err     error
46	}
47	
48	func tryPushV2Refs(ctx context.Context, target string, refs []plumbing.ReferenceName) []v2RefPushResult {
49		if len(refs) == 0 {
50			return nil
51		}
52	
53		ctx, cancel := context.WithTimeout(ctx, 2*time.Minute)
54		defer cancel()
55	
56		result, err := remote.PushWithOptions(ctx, remote.PushOptions{
57			Remote:   target,
58			RefSpecs: refSpecsForRefs(refs),
59		})
60		return parsePushRefResults(ctx, result.Output, refs, err)
61	}
62	
63	func pushV2RefsWithRecovery(ctx context.Context, target string, refs []plumbing.ReferenceName) []v2RefPushResult {
64		publishedCurrentReset, pendingErr := publishPendingV2FullGenerationPublications(ctx, target)
65		if pendingErr != nil {
66			return []v2RefPushResult{{
67				refName: plumbing.ReferenceName(paths.V2FullCurrentRefName),
68				err:     fmt.Errorf("couldn't publish pending v2 full generation refs: %w", pendingErr),
69			}}
70		}
71	
72		resultsByRef := make(map[plumbing.ReferenceName]v2RefPushResult, len(refs))
73		var retryRefs []plumbing.ReferenceName
74	
75		for _, result := range tryPushV2Refs(ctx, target, refs) {
76			if result.err == nil {
77				resultsByRef[result.refName] = result
78				continue
79			}
80			if !errors.Is(result.err, errNonFastForward) {
81				resultsByRef[result.refName] = result
82				continue
83			}
84			if publishedCurrentReset && result.refName == plumbing.ReferenceName(paths.V2FullCurrentRefName) {
85				resultsByRef[result.refName] = v2RefPushResult{
86					refName: result.refName,
87					err:     fmt.Errorf("failed to push %s after publishing pending current reset: %w", shortRefName(result.refName), result.err),
88				}
89				continue
90			}
91	
92			shortRef := shortRefName(result.refName)
93			if err := fetchAndMergeRef(ctx, target, result.refName); err != nil {
94				resultsByRef[result.refName] = v2RefPushResult{
95					refName: result.refName,
96					err:     fmt.Errorf("couldn't sync %s: %w", shortRef, err),
97				}
98				continue
99			}
100			retryRefs = append(retryRefs, result.refName)
101		}
102	
103		if len(retryRefs) > 0 {
104			for _, result := range tryPushV2Refs(ctx, target, retryRefs) {
105				if result.err != nil {
106					result.err = fmt.Errorf("failed to push %s after sync: %w", shortRefName(result.refName), result.err)
107				}
108				resultsByRef[result.refName] = result
109			}
110		}
111	
112		results := make([]v2RefPushResult, 0, len(refs))
113		for _, refName := range refs {
114			result, ok := resultsByRef[refName]
115			if !ok {
116				result = v2RefPushResult{
117					refName: refName,
118					err:     errors.New("push result missing"),
119				}
120			}
121			results = append(results, result)
122		}
123		return results
124	}
