126	func publishPendingV2FullGenerationPublications(ctx context.Context, target string) (bool, error) {
127		repo, err := OpenRepository(ctx)
128		if err != nil {
129			return false, fmt.Errorf("open repository: %w", err)
130		}
131		store := checkpoint.NewV2GitStore(repo, target)
132		publications, err := store.ReadPendingFullGenerationPublications(ctx)
133		if err != nil {
134			return false, fmt.Errorf("read pending v2 full generation publications: %w", err)
135		}
136		if len(publications) == 0 {
137			return false, nil
138		}
139	
140		archiveRefs := pendingFullArchiveRefs(publications)
141		if len(archiveRefs) > 0 {
142			for _, result := range tryPushV2Refs(ctx, target, archiveRefs) {
143				if result.err != nil {
144					return true, fmt.Errorf("push pending archive %s: %w", shortRefName(result.refName), result.err)
145				}
146			}
147		}
148	
149		resetPublications := pendingFullCurrentResetPublications(publications)
150		if len(resetPublications) == 0 {
151			if err := store.RemovePendingFullGenerationPublications(ctx, publications); err != nil {
152				return false, fmt.Errorf("clear pending v2 full generation publications: %w", err)
153			}
154			return false, nil
155		}
156	
157		currentRefName := plumbing.ReferenceName(paths.V2FullCurrentRefName)
158		localCurrentRef, err := repo.Reference(currentRefName, true)
159		if err != nil {
160			return true, fmt.Errorf("read local %s: %w", shortRefName(currentRefName), err)
161		}
162	
163		remoteCurrentHash, remoteCurrentFound, err := lsRemoteRefHash(ctx, target, currentRefName)
164		if err != nil {
165			return true, fmt.Errorf("read remote %s: %w", shortRefName(currentRefName), err)
166		}
167		if remoteCurrentFound && remoteCurrentHash == localCurrentRef.Hash() {
168			if err := store.RemovePendingFullGenerationPublications(ctx, publications); err != nil {
169				return true, fmt.Errorf("clear pending v2 full generation publications: %w", err)
170			}
171			return true, nil
172		}
173	
174		if remoteCurrentFound && !pendingResetPublicationsContainAncestor(ctx, repo, resetPublications, remoteCurrentHash) {
175			return true, fmt.Errorf("remote %s at %s is not covered by pending local archives", shortRefName(currentRefName), remoteCurrentHash)
176		}
177	
178		expectedRemoteHash := ""
179		if remoteCurrentFound {
180			expectedRemoteHash = remoteCurrentHash.String()
181		}
182		currentRefSpec := fmt.Sprintf("%s:%s", currentRefName, currentRefName)
183		if err := pushWithLease(ctx, target, currentRefSpec, currentRefName.String(), expectedRemoteHash, "push rotated "+shortRefName(currentRefName)); err != nil {
184			return true, fmt.Errorf("push rotated %s: %w", shortRefName(currentRefName), err)
185		}
186	
187		if err := store.RemovePendingFullGenerationPublications(ctx, publications); err != nil {
188			return true, fmt.Errorf("clear pending v2 full generation publications: %w", err)
189		}
190		return true, nil
191	}
