193	func pendingFullArchiveRefs(publications []checkpoint.PendingV2FullGenerationPublication) []plumbing.ReferenceName {
194		seen := make(map[plumbing.ReferenceName]struct{}, len(publications))
195		refs := make([]plumbing.ReferenceName, 0, len(publications))
196		for _, publication := range publications {
197			refName := plumbing.ReferenceName(publication.ArchiveRefName)
198			if refName == "" {
199				continue
200			}
201			if _, ok := seen[refName]; ok {
202				continue
203			}
204			seen[refName] = struct{}{}
205			refs = append(refs, refName)
206		}
207		return refs
208	}
209	
210	func pendingFullCurrentResetPublications(publications []checkpoint.PendingV2FullGenerationPublication) []checkpoint.PendingV2FullGenerationPublication {
211		resetPublications := make([]checkpoint.PendingV2FullGenerationPublication, 0, len(publications))
212		for _, publication := range publications {
213			if publication.PreviousFullCurrentHash == "" && publication.ResetFullCurrentRootHash == "" {
214				continue
215			}
216			resetPublications = append(resetPublications, publication)
217		}
218		return resetPublications
219	}
220	
221	func pendingResetPublicationsContainAncestor(ctx context.Context, repo *git.Repository, publications []checkpoint.PendingV2FullGenerationPublication, hash plumbing.Hash) bool {
222		for _, publication := range publications {
223			if publication.ArchiveCommitHash == "" {
224				continue
225			}
226			if IsAncestorOf(ctx, repo, hash, plumbing.NewHash(publication.ArchiveCommitHash)) {
227				return true
228			}
229		}
230		return false
231	}
