233	func lsRemoteRefHash(ctx context.Context, target string, refName plumbing.ReferenceName) (plumbing.Hash, bool, error) {
234		ctx, cancel := context.WithTimeout(ctx, 30*time.Second)
235		defer cancel()
236	
237		output, err := remote.LsRemote(ctx, target, refName.String())
238		if err != nil {
239			return plumbing.ZeroHash, false, fmt.Errorf("ls-remote %s: %w", refName, err)
240		}
241		for line := range strings.SplitSeq(strings.TrimSpace(string(output)), "\n") {
242			if line == "" {
243				continue
244			}
245			parts := strings.Fields(line)
246			if len(parts) < 2 || parts[1] != refName.String() {
247				continue
248			}
249			if len(parts[0]) != 40 {
250				return plumbing.ZeroHash, false, fmt.Errorf("invalid remote hash %q for %s", parts[0], refName)
251			}
252			return plumbing.NewHash(parts[0]), true, nil
253		}
254		return plumbing.ZeroHash, false, nil
255	}
