257	func refSpecsForRefs(refs []plumbing.ReferenceName) []string {
258		refSpecs := make([]string, 0, len(refs))
259		for _, refName := range refs {
260			refSpecs = append(refSpecs, fmt.Sprintf("%s:%s", refName, refName))
261		}
262		return refSpecs
263	}
264	
265	func parsePushRefResults(ctx context.Context, output string, refs []plumbing.ReferenceName, pushErr error) []v2RefPushResult {
266		parsed := make(map[plumbing.ReferenceName]v2RefPushResult, len(refs))
267		for line := range strings.SplitSeq(output, "\n") {
268			result, ok := parsePushRefStatusLine(line)
269			if ok {
270				parsed[result.refName] = result
271			}
272		}
273	
274		var fallbackErr error
275		if pushErr != nil {
276			fallbackErr = classifyPushFailure(ctx, output, pushErr)
277			if len(parsed) > 0 && len(parsed) < len(refs) {
278				logging.Debug(ctx, "push-v2: incomplete push porcelain output",
279					slog.Int("parsed_refs", len(parsed)),
280					slog.Int("expected_refs", len(refs)),
281					slog.String("error", pushErr.Error()),
282					slog.String("output", output),
283				)
284			}
285		}
286	
287		results := make([]v2RefPushResult, 0, len(refs))
288		for _, refName := range refs {
289			if result, ok := parsed[refName]; ok {
290				results = append(results, result)
291				continue
292			}
293			if pushErr != nil && len(parsed) > 0 {
294				results = append(results, v2RefPushResult{
295					refName: refName,
296					err:     fmt.Errorf("status missing for %s", shortRefName(refName)),
297				})
298				continue
299			}
300			err := fallbackErr
301			if err != nil {
302				err = fmt.Errorf("failed to push %s: %w", shortRefName(refName), err)
303			}
304			results = append(results, v2RefPushResult{
305				refName: refName,
306				err:     err,
307			})
308		}
309		return results
310	}
311	
312	func parsePushRefStatusLine(line string) (v2RefPushResult, bool) {
313		fields := strings.Split(line, "\t")
314		if len(fields) < 2 || fields[0] == "" {
315			return v2RefPushResult{}, false
316		}
317	
318		refName, ok := pushStatusRef(fields[1])
319		if !ok {
320			return v2RefPushResult{}, false
321		}
322	
323		switch fields[0][0] {
324		case '!':
325			err := classifyPushOutput(strings.Join(fields[2:], "\t"))
326			return v2RefPushResult{
327				refName: refName,
328				err:     fmt.Errorf("failed to push %s: %w", shortRefName(refName), err),
329			}, true
330		case '=':
331			return v2RefPushResult{
332				refName: refName,
333				result:  pushResult{upToDate: true},
334			}, true
335		default:
336			return v2RefPushResult{refName: refName}, true
337		}
338	}
339	
340	func pushStatusRef(statusRef string) (plumbing.ReferenceName, bool) {
341		_, dst, ok := strings.Cut(statusRef, ":")
342		if !ok || dst == "" {
343			return "", false
344		}
345		return plumbing.ReferenceName(dst), true
346	}
347	
348	// fetchAndMergeRef fetches a remote custom ref and merges it into the local ref.
349	// Uses the same tree-flattening merge as v1 (sharded paths are unique, so no conflicts).
350	//
351	// For /full/current: if the remote has archived generations not present locally,
352	// another machine rotated. In that case, local data is merged into the latest
353	// archived generation instead of into /full/current (see handleRotationConflict).
354	func fetchAndMergeRef(ctx context.Context, target string, refName plumbing.ReferenceName) error {
355		ctx, cancel := context.WithTimeout(ctx, 2*time.Minute)
356		defer cancel()
357	
358		fetchTarget, err := remote.ResolveFetchTarget(ctx, target)
359		if err != nil {
360			return fmt.Errorf("resolve fetch target: %w", err)
361		}
362	
363		// Fetch to a temp ref
364		tmpRefSuffix := strings.ReplaceAll(string(refName), "/", "-")
365		tmpRefName := plumbing.ReferenceName("refs/entire-fetch-tmp/" + tmpRefSuffix)
366		refSpec := fmt.Sprintf("+%s:%s", refName, tmpRefName)
367	
368		if output, err := remote.Fetch(ctx, remote.FetchOptions{
369			Remote:    fetchTarget,
370			RefSpecs:  []string{refSpec},
371			NoTags:    true,
372			ExtraArgs: []string{"--no-write-fetch-head"},
373		}); err != nil {
374			return fmt.Errorf("fetch failed: %s", output)
375		}
376	
377		repo, err := OpenRepository(ctx)
378		if err != nil {
379			return fmt.Errorf("failed to open repository: %w", err)
380		}
381		defer func() {
382			_ = repo.Storer.RemoveReference(tmpRefName) //nolint:errcheck // cleanup is best-effort
383		}()
384	
385		// Check for rotation conflict on /full/current
386		if refName == plumbing.ReferenceName(paths.V2FullCurrentRefName) {
387			remoteRotationArchives, detectErr := detectRemoteRotationArchives(ctx, target, repo)
388			if detectErr == nil && len(remoteRotationArchives) > 0 {
389				return handleRotationConflict(ctx, target, fetchTarget, repo, refName, tmpRefName, remoteRotationArchives)
390			}
391		}
392	
393		// Standard tree merge (no rotation detected)
394		localRef, err := repo.Reference(refName, true)
395		if err != nil {
396			return fmt.Errorf("failed to get local ref: %w", err)
397		}
398		localCommit, err := repo.CommitObject(localRef.Hash())
399		if err != nil {
400			return fmt.Errorf("failed to get local commit: %w", err)
401		}
402		localTree, err := localCommit.Tree()
403		if err != nil {
404			return fmt.Errorf("failed to get local tree: %w", err)
405		}
406	
407		remoteRef, err := repo.Reference(tmpRefName, true)
408		if err != nil {
409			return fmt.Errorf("failed to get remote ref: %w", err)
410		}
411		remoteCommit, err := repo.CommitObject(remoteRef.Hash())
412		if err != nil {
413			return fmt.Errorf("failed to get remote commit: %w", err)
414		}
415		remoteTree, err := remoteCommit.Tree()
416		if err != nil {
417			return fmt.Errorf("failed to get remote tree: %w", err)
418		}
419	
420		entries := make(map[string]object.TreeEntry)
421		if err := checkpoint.FlattenTree(repo, localTree, "", entries); err != nil {
422			return fmt.Errorf("failed to flatten local tree: %w", err)
423		}
424		if err := checkpoint.FlattenTree(repo, remoteTree, "", entries); err != nil {
425			return fmt.Errorf("failed to flatten remote tree: %w", err)
426		}
427	
428		mergedTreeHash, err := checkpoint.BuildTreeFromEntries(ctx, repo, entries)
429		if err != nil {
430			return fmt.Errorf("failed to build merged tree: %w", err)
431		}
432	
433		mergeCommitHash, err := createMergeCommitCommon(ctx, repo, mergedTreeHash,
434			[]plumbing.Hash{localRef.Hash(), remoteRef.Hash()},
435			"Merge remote "+shortRefName(refName))
436		if err != nil {
437			return fmt.Errorf("failed to create merge commit: %w", err)
438		}
439	
440		newRef := plumbing.NewHashReference(refName, mergeCommitHash)
441		if err := repo.Storer.SetReference(newRef); err != nil {
442			return fmt.Errorf("failed to update ref: %w", err)
443		}
444	
445		return nil
446	}
