448	// detectRemoteRotationArchives discovers archived generation refs on the remote
449	// that are missing locally or whose local ref hash differs from the remote ref
450	// hash. Returns them sorted ascending (oldest first).
451	func detectRemoteRotationArchives(ctx context.Context, target string, repo *git.Repository) ([]string, error) {
452		ctx, cancel := context.WithTimeout(ctx, 30*time.Second)
453		defer cancel()
454	
455		output, err := remote.LsRemote(ctx, target, paths.V2FullRefPrefix+"*")
456		if err != nil {
457			return nil, fmt.Errorf("ls-remote failed: %w", err)
458		}
459	
460		var remoteRotationArchives []string
461		for line := range strings.SplitSeq(strings.TrimSpace(string(output)), "\n") {
462			if line == "" {
463				continue
464			}
465			parts := strings.Fields(line)
466			if len(parts) < 2 {
467				continue
468			}
469			refName := parts[1]
470			suffix := strings.TrimPrefix(refName, paths.V2FullRefPrefix)
471			if suffix == "current" || !checkpoint.GenerationRefPattern.MatchString(suffix) {
472				continue
473			}
474			if len(parts[0]) != 40 {
475				return nil, fmt.Errorf("invalid remote archive hash %q for %s", parts[0], refName)
476			}
477			remoteHash := plumbing.NewHash(parts[0])
478			localRef, err := repo.Reference(plumbing.ReferenceName(refName), true)
479			if err != nil || localRef.Hash() != remoteHash {
480				remoteRotationArchives = append(remoteRotationArchives, suffix)
481			}
482		}
483	
484		sort.Strings(remoteRotationArchives)
485		return remoteRotationArchives, nil
486	}
