495	func readFetchedRemoteRotationArchive(repo *git.Repository, archive string) (fetchedRemoteRotationArchive, error) {
496		archiveRefName := plumbing.ReferenceName(paths.V2FullRefPrefix + archive)
497		archiveTmpRef := plumbing.ReferenceName("refs/entire-fetch-tmp/archive-" + archive)
498		archiveRef, err := repo.Reference(archiveTmpRef, true)
499		if err != nil {
500			return fetchedRemoteRotationArchive{}, fmt.Errorf("failed to get archived ref: %w", err)
501		}
502		archiveCommit, err := repo.CommitObject(archiveRef.Hash())
503		if err != nil {
504			return fetchedRemoteRotationArchive{}, fmt.Errorf("failed to get archive commit: %w", err)
505		}
506		archiveTree, err := archiveCommit.Tree()
507		if err != nil {
508			return fetchedRemoteRotationArchive{}, fmt.Errorf("failed to get archive tree: %w", err)
509		}
510	
511		return fetchedRemoteRotationArchive{
512			refName:    archiveRefName,
513			tmpRefName: archiveTmpRef,
514			ref:        archiveRef,
515			tree:       archiveTree,
516		}, nil
517	}
518	
519	func fetchRelatedRemoteRotationArchive(ctx context.Context, fetchTarget string, repo *git.Repository, archives []string, localCurrentHash plumbing.Hash) (fetchedRemoteRotationArchive, error) {
520		refSpecs := make([]string, 0, len(archives))
521		for _, archive := range archives {
522			archiveRefName := plumbing.ReferenceName(paths.V2FullRefPrefix + archive)
523			archiveTmpRef := plumbing.ReferenceName("refs/entire-fetch-tmp/archive-" + archive)
524			refSpecs = append(refSpecs, fmt.Sprintf("+%s:%s", archiveRefName, archiveTmpRef))
525		}
526		if output, fetchErr := remote.Fetch(ctx, remote.FetchOptions{
527			Remote:    fetchTarget,
528			RefSpecs:  refSpecs,
529			NoTags:    true,
530			ExtraArgs: []string{"--no-write-fetch-head"},
531		}); fetchErr != nil {
532			return fetchedRemoteRotationArchive{}, fmt.Errorf("fetch archived generations failed: %s", output)
533		}
534	
535		localCurrentAncestors, ok := currentGenerationAncestors(ctx, repo, localCurrentHash)
536		if !ok {
537			return fetchedRemoteRotationArchive{}, errors.New("failed to read local /full/current history")
538		}
539		for _, archive := range archives {
540			fetched, err := readFetchedRemoteRotationArchive(repo, archive)
541			if err != nil {
542				return fetchedRemoteRotationArchive{}, err
543			}
544			if archiveSharesHistoryWithCurrentGeneration(ctx, repo, localCurrentAncestors, fetched.ref.Hash()) {
545				return fetched, nil
546			}
547			_ = repo.Storer.RemoveReference(fetched.tmpRefName) //nolint:errcheck // cleanup is best-effort
548		}
549		return fetchedRemoteRotationArchive{}, errors.New("no remote archive shares history with local /full/current")
550	}
551	
552	func currentGenerationAncestors(ctx context.Context, repo *git.Repository, currentHash plumbing.Hash) (map[plumbing.Hash]struct{}, bool) {
553		ancestors := make(map[plumbing.Hash]struct{})
554		iter, err := repo.Log(&git.LogOptions{From: currentHash})
555		if err != nil {
556			return nil, false
557		}
558		defer iter.Close()
559	
560		count := 0
561		_ = iter.ForEach(func(c *object.Commit) error { //nolint:errcheck // Best-effort search, errors are non-fatal
562			if err := ctx.Err(); err != nil {
563				return err //nolint:wrapcheck // Propagating context cancellation
564			}
565			count++
566			if count > MaxCommitTraversalDepth {
567				return errStop
568			}
569			ancestors[c.Hash] = struct{}{}
570			return nil
571		})
572		return ancestors, true
573	}
574	
575	func archiveSharesHistoryWithCurrentGeneration(ctx context.Context, repo *git.Repository, currentAncestors map[plumbing.Hash]struct{}, archiveHash plumbing.Hash) bool {
576		if _, ok := currentAncestors[archiveHash]; ok {
577			return true
578		}
579	
580		iter, err := repo.Log(&git.LogOptions{From: archiveHash})
581		if err != nil {
582			return false
583		}
584		defer iter.Close()
585	
586		found := false
587		count := 0
588		_ = iter.ForEach(func(c *object.Commit) error { //nolint:errcheck // Best-effort search, errors are non-fatal
589			if err := ctx.Err(); err != nil {
590				return err //nolint:wrapcheck // Propagating context cancellation
591			}
592			count++
593			if count > MaxCommitTraversalDepth {
594				return errStop
595			}
596			if _, ok := currentAncestors[c.Hash]; ok {
597				found = true
598				return errStop
599			}
600			return nil
601		})
602		return found
603	}
