605	// handleRotationConflict handles the case where remote /full/current was rotated.
606	// Merges local /full/current into the related remote archived generation to avoid
607	// duplicating checkpoint data, then adopts remote's /full/current as local.
608	func handleRotationConflict(ctx context.Context, target, fetchTarget string, repo *git.Repository, refName, tmpRefName plumbing.ReferenceName, remoteRotationArchives []string) error {
609		// Get local /full/current state before selecting an archive. If the remote
610		// rotated multiple times, the latest archive may belong to a different
611		// generation chain.
612		localRef, err := repo.Reference(refName, true)
613		if err != nil {
614			return fmt.Errorf("failed to get local ref: %w", err)
615		}
616		localCommit, err := repo.CommitObject(localRef.Hash())
617		if err != nil {
618			return fmt.Errorf("failed to get local commit: %w", err)
619		}
620		localTree, err := localCommit.Tree()
621		if err != nil {
622			return fmt.Errorf("failed to get local tree: %w", err)
623		}
624	
625		archive, err := fetchRelatedRemoteRotationArchive(ctx, fetchTarget, repo, remoteRotationArchives, localRef.Hash())
626		if err != nil {
627			return fmt.Errorf("failed to find related archived generation: %w", err)
628		}
629		defer func() {
630			_ = repo.Storer.RemoveReference(archive.tmpRefName) //nolint:errcheck // cleanup is best-effort
631		}()
632	
633		// Tree-merge local /full/current into archived generation.
634		// Git content-addressing deduplicates shared shard paths automatically.
635		entries := make(map[string]object.TreeEntry)
636		if err := checkpoint.FlattenTree(repo, archive.tree, "", entries); err != nil {
637			return fmt.Errorf("failed to flatten archive tree: %w", err)
638		}
639		if err := checkpoint.FlattenTree(repo, localTree, "", entries); err != nil {
640			return fmt.Errorf("failed to flatten local tree: %w", err)
641		}
642	
643		// Update generation.json timestamps if present in the merged tree.
644		// Use the local /full/current HEAD commit time as the newest checkpoint time
645		// (more accurate than time.Now() for cleanup scheduling).
646		if genEntry, exists := entries[paths.GenerationFileName]; exists {
647			if updatedEntry, updateErr := updateGenerationTimestamps(repo, genEntry.Hash, localCommit.Committer.When.UTC()); updateErr == nil {
648				entries[paths.GenerationFileName] = updatedEntry
649			} else {
650				logging.Warn(ctx, "rotation recovery: failed to update generation timestamps, using stale values",
651					slog.String("error", updateErr.Error()),
652				)
653			}
654		}
655	
656		mergedTreeHash, err := checkpoint.BuildTreeFromEntries(ctx, repo, entries)
657		if err != nil {
658			return fmt.Errorf("failed to build merged tree: %w", err)
659		}
660	
661		// Create commit parented on archive's commit (fast-forward)
662		mergeCommitHash, err := createMergeCommitCommon(ctx, repo, mergedTreeHash,
663			[]plumbing.Hash{archive.ref.Hash()},
664			"Merge local checkpoints into archived generation")
665		if err != nil {
666			return fmt.Errorf("failed to create merge commit: %w", err)
667		}
668	
669		// Update local archived ref and push it
670		newArchiveRef := plumbing.NewHashReference(archive.refName, mergeCommitHash)
671		if err := repo.Storer.SetReference(newArchiveRef); err != nil {
672			return fmt.Errorf("failed to update archive ref: %w", err)
673		}
674	
675		if pushErr := tryPushRef(ctx, target, archive.refName); pushErr != nil {
676			return fmt.Errorf("failed to push updated archive: %w", pushErr)
677		}
678	
679		// Adopt remote's /full/current as local
680		remoteRef, err := repo.Reference(tmpRefName, true)
681		if err != nil {
682			return fmt.Errorf("failed to get fetched /full/current: %w", err)
683		}
684		adoptedRef := plumbing.NewHashReference(refName, remoteRef.Hash())
685		if err := repo.Storer.SetReference(adoptedRef); err != nil {
686			return fmt.Errorf("failed to adopt remote /full/current: %w", err)
687		}
688	
689		return nil
690	}
691	
692	// updateGenerationTimestamps reads generation.json from a blob, updates
693	// newest_checkpoint_at if the provided newestFromLocal is newer, and returns
694	// an updated tree entry. Uses the local commit timestamp rather than
695	// time.Now() so cleanup scheduling reflects actual checkpoint creation time.
696	func updateGenerationTimestamps(repo *git.Repository, genBlobHash plumbing.Hash, newestFromLocal time.Time) (object.TreeEntry, error) {
697		blob, err := repo.BlobObject(genBlobHash)
698		if err != nil {
699			return object.TreeEntry{}, fmt.Errorf("failed to read generation blob: %w", err)
700		}
701		reader, err := blob.Reader()
702		if err != nil {
703			return object.TreeEntry{}, fmt.Errorf("failed to open generation blob reader: %w", err)
704		}
705		defer reader.Close()
706	
707		data, err := io.ReadAll(reader)
708		if err != nil {
709			return object.TreeEntry{}, fmt.Errorf("failed to read generation blob data: %w", err)
710		}
711	
712		var gen checkpoint.GenerationMetadata
713		if err := json.Unmarshal(data, &gen); err != nil {
714			return object.TreeEntry{}, fmt.Errorf("failed to parse generation.json: %w", err)
715		}
716	
717		if newestFromLocal.After(gen.NewestCheckpointAt) {
718			gen.NewestCheckpointAt = newestFromLocal
719		}
720	
721		updatedData, err := jsonutil.MarshalIndentWithNewline(gen, "", "  ")
722		if err != nil {
723			return object.TreeEntry{}, fmt.Errorf("failed to marshal generation.json: %w", err)
724		}
725	
726		newBlobHash, err := checkpoint.CreateBlobFromContent(repo, updatedData)
727		if err != nil {
728			return object.TreeEntry{}, fmt.Errorf("failed to create generation blob: %w", err)
729		}
730	
731		return object.TreeEntry{
732			Name: paths.GenerationFileName,
733			Mode: filemode.Regular,
734			Hash: newBlobHash,
735		}, nil
736	}
