738	// pushV2Refs pushes v2 checkpoint refs to the target.
739	// Pushes active refs in one git push. Pending full-generation publications are
740	// handled separately before /full/current recovery.
741	func pushV2Refs(ctx context.Context, target string) {
742		refs := v2RefsToPush(ctx)
743		if len(refs) == 0 && !hasPendingV2FullGenerationPublications(ctx, target) {
744			return
745		}
746	
747		fmt.Fprintln(os.Stderr, "[entire] Syncing and pushing v2 checkpoints...")
748		pushNames := shortRefNames(refs)
749		if len(pushNames) == 0 {
750			pushNames = []string{"pending v2/full generations"}
751		}
752		fmt.Fprintf(os.Stderr, "[entire] Pushing %s...\n", strings.Join(pushNames, ", "))
753	
754		results := pushV2RefsWithRecovery(ctx, target, refs)
755		var failures []error
756		var successfulRefs []plumbing.ReferenceName
757		pushedContent := false
758		for _, result := range results {
759			if result.err != nil {
760				failures = append(failures, result.err)
761				continue
762			}
763			successfulRefs = append(successfulRefs, result.refName)
764			if !result.result.upToDate {
765				pushedContent = true
766			}
767		}
768	
769		if len(failures) > 0 {
770			printV2PartialPushResult(os.Stderr, successfulRefs, failures)
771			printCheckpointRemoteHint(target)
772			if pushedContent {
773				printSettingsCommitHint(ctx, target)
774			}
775			printCheckpointsV2MigrationHint(ctx)
776			return
777		}
778	
779		fmt.Fprintln(os.Stderr, "[entire] All v2 checkpoints pushed")
780		if pushedContent {
781			printSettingsCommitHint(ctx, target)
782		}
783		printCheckpointsV2MigrationHint(ctx)
784	}
