200	// v2DoctorTmpRef is the temporary ref used by doctor to fetch and compare the remote v2 /main.
201	// Uses the refs/entire-fetch-tmp/ namespace consistent with checkpoint_remote.go.
202	const v2DoctorTmpRef = "refs/entire-fetch-tmp/doctor-v2-main"
203	
204	// IsV2MainDisconnected checks whether the local v2 /main ref and the remote
205	// v2 /main ref exist but share no common ancestor. Uses git ls-remote to
206	// discover the remote ref (custom refs don't have remote-tracking refs).
207	//
208	// remote is the git remote name, URL, or local path to check against.
209	// Returns (false, nil) if either ref doesn't exist or they share ancestry.
210	func IsV2MainDisconnected(ctx context.Context, repo *git.Repository, remote string) (bool, error) {
211		refName := plumbing.ReferenceName(paths.V2MainRefName)
212	
213		localRef, err := repo.Reference(refName, true)
214		if errors.Is(err, plumbing.ErrReferenceNotFound) {
215			return false, nil
216		}
217		if err != nil {
218			return false, fmt.Errorf("failed to check local v2 /main ref: %w", err)
219		}
220	
221		repoPath, err := getRepoPath(repo)
222		if err != nil {
223			return false, err
224		}
225	
226		remoteHash, err := lsRemoteRef(ctx, repoPath, remote, paths.V2MainRefName)
227		if err != nil {
228			return false, fmt.Errorf("failed to ls-remote v2 /main: %w", err)
229		}
230		if remoteHash == plumbing.ZeroHash {
231			return false, nil // Remote doesn't have the ref
232		}
233	
234		if localRef.Hash() == remoteHash {
235			return false, nil
236		}
237	
238		// Fetch remote ref to temporary local ref for merge-base check.
239		// Use the fetched hash (not ls-remote hash) since the remote may have advanced.
240		if fetchErr := fetchRefToTemp(ctx, repoPath, remote, paths.V2MainRefName, v2DoctorTmpRef); fetchErr != nil {
241			return false, fmt.Errorf("failed to fetch remote v2 /main: %w", fetchErr)
242		}
243		defer cleanupTmpRef(repo)
244	
245		fetchedHash, err := resolveRefHash(repo, v2DoctorTmpRef)
246		if err != nil {
247			return false, fmt.Errorf("failed to read fetched v2 /main ref: %w", err)
248		}
249	
250		if localRef.Hash() == fetchedHash {
251			return false, nil
252		}
253	
254		return isDisconnected(ctx, repoPath, localRef.Hash().String(), fetchedHash.String())
255	}
256	
257	// ReconcileDisconnectedV2Ref detects and repairs disconnected local/remote
258	// v2 /main refs. Same strategy as v1: cherry-pick local commits onto remote tip.
259	// The remote is discovered via git ls-remote and fetched to a temp ref.
260	//
261	// remote is the git remote name, URL, or local path.
262	func ReconcileDisconnectedV2Ref(
263		ctx context.Context,
264		repo *git.Repository,
265		remote string,
266		w io.Writer,
267	) error {
268		refName := plumbing.ReferenceName(paths.V2MainRefName)
269	
270		localRef, err := repo.Reference(refName, true)
271		if errors.Is(err, plumbing.ErrReferenceNotFound) {
272			return nil
273		}
274		if err != nil {
275			return fmt.Errorf("failed to check local v2 /main ref: %w", err)
276		}
277	
278		repoPath, err := getRepoPath(repo)
279		if err != nil {
280			return err
281		}
282	
283		remoteHash, err := lsRemoteRef(ctx, repoPath, remote, paths.V2MainRefName)
284		if err != nil {
285			return fmt.Errorf("failed to ls-remote v2 /main: %w", err)
286		}
287		if remoteHash == plumbing.ZeroHash {
288			return nil
289		}
290	
291		if localRef.Hash() == remoteHash {
292			return nil
293		}
294	
295		if fetchErr := fetchRefToTemp(ctx, repoPath, remote, paths.V2MainRefName, v2DoctorTmpRef); fetchErr != nil {
296			return fmt.Errorf("failed to fetch remote v2 /main: %w", fetchErr)
297		}
298		defer cleanupTmpRef(repo)
299	
300		// Use the fetched hash (not ls-remote hash) since the remote may have advanced.
301		fetchedHash, err := resolveRefHash(repo, v2DoctorTmpRef)
302		if err != nil {
303			return fmt.Errorf("failed to read fetched v2 /main ref: %w", err)
304		}
305	
306		if localRef.Hash() == fetchedHash {
307			return nil
308		}
309	
310		disconnected, err := isDisconnected(ctx, repoPath, localRef.Hash().String(), fetchedHash.String())
311		if err != nil {
312			return fmt.Errorf("failed to check v2 /main ancestry: %w", err)
313		}
314		if !disconnected {
315			return nil
316		}
317	
318		fmt.Fprintln(w, "[entire] Detected disconnected v2 /main refs (local and remote share no common ancestor)")
319	
320		localCommits, err := collectCommitChain(repo, localRef.Hash())
321		if err != nil {
322			return fmt.Errorf("failed to collect local commits: %w", err)
323		}
324	
325		var dataCommits []*object.Commit
326		for _, c := range localCommits {
327			tree, treeErr := c.Tree()
328			if treeErr != nil {
329				return fmt.Errorf("failed to read tree for commit %s: %w", c.Hash.String()[:7], treeErr)
330			}
331			if len(tree.Entries) > 0 {
332				dataCommits = append(dataCommits, c)
333			}
334		}
335	
336		if len(dataCommits) == 0 {
337			ref := plumbing.NewHashReference(refName, fetchedHash)
338			if setErr := repo.Storer.SetReference(ref); setErr != nil {
339				return fmt.Errorf("failed to reset v2 /main to remote: %w", setErr)
340			}
341			fmt.Fprintln(w, "[entire] Done — local had no checkpoint data, reset to remote")
342			return nil
343		}
344	
345		fmt.Fprintf(w, "[entire] Cherry-picking %d local checkpoint(s) onto remote...\n", len(dataCommits))
346	
347		newTip, err := cherryPickOnto(ctx, repo, fetchedHash, dataCommits)
348		if err != nil {
349			return fmt.Errorf("failed to cherry-pick local commits onto remote: %w", err)
350		}
351	
352		ref := plumbing.NewHashReference(refName, newTip)
353		if setErr := repo.Storer.SetReference(ref); setErr != nil {
354			return fmt.Errorf("failed to update v2 /main ref: %w", setErr)
355		}
356	
357		fmt.Fprintln(w, "[entire] Done — all local and remote checkpoints preserved")
358		return nil
359	}
