361	// lsRemoteRef runs git ls-remote and returns the hash for a specific ref.
362	// Returns plumbing.ZeroHash if the ref doesn't exist on the remote.
363	func lsRemoteRef(ctx context.Context, repoPath, remoteName, refName string) (plumbing.Hash, error) {
364		ctx, cancel := context.WithTimeout(ctx, 10*time.Second)
365		defer cancel()
366	
367		fetchTarget, err := remote.ResolveFetchTarget(ctx, remoteName)
368		if err != nil {
369			return plumbing.ZeroHash, fmt.Errorf("resolve fetch target for ls-remote: %w", err)
370		}
371	
372		output, err := remote.LsRemoteInDir(ctx, repoPath, fetchTarget, refName)
373		if err != nil {
374			return plumbing.ZeroHash, fmt.Errorf("git ls-remote %s failed: %w", remote.RedactURL(fetchTarget), err)
375		}
376	
377		line := strings.TrimSpace(string(output))
378		if line == "" {
379			return plumbing.ZeroHash, nil
380		}
381	
382		parts := strings.Fields(line)
383		if len(parts) < 2 {
384			return plumbing.ZeroHash, nil
385		}
386	
387		return plumbing.NewHash(parts[0]), nil
388	}
