156	// ComputeGenerationCheckpointTimestamps derives timestamps from the checkpoints
157	// present in a /full/* tree. It prefers created_at from v2 /main metadata and
158	// falls back to top-level transcript event timestamps for older or partial v2 data.
159	func (s *V2GitStore) ComputeGenerationCheckpointTimestamps(rootTreeHash plumbing.Hash) (GenerationMetadata, bool, error) {
160		mainTree, mainTreeErr := s.v2MainTree()
161		if mainTreeErr != nil {
162			mainTree = nil
163		}
164		return s.ComputeGenerationTimestampsFromTrees(rootTreeHash, mainTree)
165	}
