167	// ComputeGenerationTimestampsFromTrees walks every checkpoint in rootTreeHash
168	// and aggregates per-checkpoint timestamps. When mainTree is non-nil, /main
169	// metadata.json is consulted before falling back to the raw transcript inside
170	// the checkpoint's full-tree. Returns found=false when any checkpoint cannot
171	// produce a timestamp; callers decide their own fallback (e.g. read existing
172	// generation.json, recompute from in-memory data, or surface an error).
173	func (s *V2GitStore) ComputeGenerationTimestampsFromTrees(rootTreeHash plumbing.Hash, mainTree *object.Tree) (GenerationMetadata, bool, error) {
174		if rootTreeHash == plumbing.ZeroHash {
175			return GenerationMetadata{}, false, nil
176		}
177	
178		rootTree, err := s.repo.TreeObject(rootTreeHash)
179		if err != nil {
180			return GenerationMetadata{}, false, fmt.Errorf("failed to read generation tree: %w", err)
181		}
182	
183		var gen GenerationMetadata
184		found := false
185		missingCheckpointTimestamp := false
186		err = WalkCheckpointShards(s.repo, rootTree, func(cpID id.CheckpointID, cpTreeHash plumbing.Hash) error {
187			if mainTree != nil {
188				if cpGen, ok := s.checkpointTimestampRangeFromMain(mainTree, cpID); ok {
189					mergeGenerationRange(&gen, &found, cpGen)
190					return nil
191				}
192			}
193	
194			cpTree, treeErr := s.repo.TreeObject(cpTreeHash)
195			if treeErr != nil {
196				missingCheckpointTimestamp = true
197				return nil //nolint:nilerr // Skip unreadable checkpoint trees and fall back to generation.json.
198			}
199			if cpGen, ok := checkpointTimestampRangeFromFullTree(cpTree); ok {
200				mergeGenerationRange(&gen, &found, cpGen)
201				return nil
202			}
203			missingCheckpointTimestamp = true
204			return nil
205		})
206		if err != nil {
207			return GenerationMetadata{}, false, err
208		}
209		if missingCheckpointTimestamp {
210			return GenerationMetadata{}, false, nil
211		}
212	
213		return gen, found, nil
214	}
