216	// computeGenerationTimestamps derives timestamps for a generation being archived.
217	// It uses checkpoint metadata/transcript timestamps rather than git commit times
218	// so migration and ref-repair commits don't reset retention age.
219	func (s *V2GitStore) computeGenerationTimestamps(rootTreeHash plumbing.Hash) GenerationMetadata {
220		if gen, ok, err := s.ComputeGenerationCheckpointTimestamps(rootTreeHash); err == nil && ok {
221			return gen
222		}
223		return s.computeGenerationTimestampsFromCommitHistory()
224	}
