226	func (s *V2GitStore) computeGenerationTimestampsFromCommitHistory() GenerationMetadata {
227		now := time.Now().UTC()
228		fallback := GenerationMetadata{OldestCheckpointAt: now, NewestCheckpointAt: now}
229	
230		refName := plumbing.ReferenceName(paths.V2FullCurrentRefName)
231		ref, err := s.repo.Reference(refName, true)
232		if err != nil {
233			return fallback
234		}
235	
236		commit, err := s.repo.CommitObject(ref.Hash())
237		if err != nil {
238			return fallback
239		}
240	
241		newest := commit.Committer.When.UTC()
242	
243		// Walk parents to find the oldest commit in this generation
244		iter := commit
245		for len(iter.ParentHashes) > 0 {
246			parent, parentErr := s.repo.CommitObject(iter.ParentHashes[0])
247			if parentErr != nil {
248				break
249			}
250			iter = parent
251		}
252		oldest := iter.Committer.When.UTC()
253	
254		return GenerationMetadata{
255			OldestCheckpointAt: oldest,
256			NewestCheckpointAt: newest,
257		}
258	}
