276	func (s *V2GitStore) checkpointTimestampRangeFromMain(mainTree *object.Tree, cpID id.CheckpointID) (GenerationMetadata, bool) {
277		cpTree, err := mainTree.Tree(cpID.Path())
278		if err != nil {
279			return GenerationMetadata{}, false
280		}
281	
282		var gen GenerationMetadata
283		found := false
284		for _, entry := range cpTree.Entries {
285			if entry.Mode != filemode.Dir {
286				continue
287			}
288			if _, err := strconv.Atoi(entry.Name); err != nil {
289				continue
290			}
291			sessionTree, err := s.repo.TreeObject(entry.Hash)
292			if err != nil {
293				continue
294			}
295			metadataFile, err := sessionTree.File(paths.MetadataFileName)
296			if err != nil {
297				continue
298			}
299			metadataContent, err := metadataFile.Contents()
300			if err != nil {
301				continue
302			}
303			var metadata CommittedMetadata
304			if err := json.Unmarshal([]byte(metadataContent), &metadata); err != nil || metadata.CreatedAt.IsZero() {
305				continue
306			}
307			MergeGenerationTime(&gen, &found, metadata.CreatedAt.UTC())
308		}
309		return gen, found
310	}
