312	func checkpointTimestampRangeFromFullTree(cpTree *object.Tree) (GenerationMetadata, bool) {
313		var gen GenerationMetadata
314		found := false
315		for _, entry := range cpTree.Entries {
316			if entry.Mode != filemode.Dir {
317				continue
318			}
319			if _, err := strconv.Atoi(entry.Name); err != nil {
320				continue
321			}
322			sessionTree, err := cpTree.Tree(entry.Name)
323			if err != nil {
324				continue
325			}
326			transcript, err := readTranscriptFromObjectTree(sessionTree, "")
327			if err != nil || len(transcript) == 0 {
328				continue
329			}
330			if transcriptGen, ok := timestampRangeFromTranscript(transcript); ok {
331				mergeGenerationRange(&gen, &found, transcriptGen)
332			}
333		}
334		return gen, found
335	}
