387	// MergeGenerationTime expands the generation timestamp envelope to include ts.
388	// The found flag is set the first time a non-zero timestamp is observed.
389	func MergeGenerationTime(gen *GenerationMetadata, found *bool, ts time.Time) {
390		if ts.IsZero() {
391			return
392		}
393		ts = ts.UTC()
394		if !*found {
395			gen.OldestCheckpointAt = ts
396			gen.NewestCheckpointAt = ts
397			*found = true
398			return
399		}
400		if ts.Before(gen.OldestCheckpointAt) {
401			gen.OldestCheckpointAt = ts
402		}
403		if ts.After(gen.NewestCheckpointAt) {
404			gen.NewestCheckpointAt = ts
405		}
406	}
