408	// generationRefWidth is the zero-padded width of archived generation ref names.
409	const generationRefWidth = 13
410	
411	// ArchivedGenerationRefName returns the full ref name for an archived generation number.
412	func ArchivedGenerationRefName(number int) plumbing.ReferenceName {
413		return plumbing.ReferenceName(fmt.Sprintf("%s%0*d", paths.V2FullRefPrefix, generationRefWidth, number))
414	}
