416	// GenerationRefPattern matches exactly 13 digits (the archived generation ref suffix format).
417	var GenerationRefPattern = regexp.MustCompile(`^\d{13}$`)
418	
419	// listArchivedGenerations returns the names of all archived generation refs
420	// (everything under V2FullRefPrefix matching the expected numeric format), sorted ascending.
421	func (s *V2GitStore) ListArchivedGenerations() ([]string, error) {
422		refs, err := s.repo.References()
423		if err != nil {
424			return nil, fmt.Errorf("failed to list references: %w", err)
425		}
426	
427		var archived []string
428		err = refs.ForEach(func(ref *plumbing.Reference) error {
429			name := ref.Name().String()
430			if !strings.HasPrefix(name, paths.V2FullRefPrefix) {
431				return nil
432			}
433			suffix := strings.TrimPrefix(name, paths.V2FullRefPrefix)
434			if suffix == "current" || !GenerationRefPattern.MatchString(suffix) {
435				return nil
436			}
437			archived = append(archived, suffix)
438			return nil
439		})
440		if err != nil {
441			return nil, fmt.Errorf("failed to iterate references: %w", err)
442		}
443	
444		sort.Strings(archived)
445		return archived, nil
446	}
