469	// RotateCurrentGenerationIfNeeded archives /full/current when it has reached
470	// maxCheckpoints. It returns the archived ref name when this call completes
471	// a rotation.
472	func (s *V2GitStore) RotateCurrentGenerationIfNeeded(ctx context.Context, maxCheckpoints int) (plumbing.ReferenceName, bool, error) {
473		if maxCheckpoints <= 0 {
474			maxCheckpoints = s.maxCheckpoints()
475		}
476	
477		// This is a 2-phase operation:
478		//
479		//  1. Archive: determine the next generation number, create a new ref pointing
480		//     to the current /full/current commit.
481		//  2. Reset: create a fresh orphan commit with an empty tree, point
482		//     /full/current at it.
483		refName := plumbing.ReferenceName(paths.V2FullCurrentRefName)
484	
485		// Guard against concurrent rotation: re-read /full/current and check if
486		// it's still above the threshold. If not, another instance already rotated.
487		_, currentTreeHash, err := s.GetRefState(refName)
488		if err != nil {
489			return "", false, fmt.Errorf("rotation: failed to read /full/current: %w", err)
490		}
491		checkpointCount, err := s.CountCheckpointsInTree(currentTreeHash)
492		if err != nil {
493			return "", false, fmt.Errorf("rotation: failed to count checkpoints: %w", err)
494		}
495		if checkpointCount < maxCheckpoints {
496			return "", false, nil
497		}
498	
499		currentRef, err := s.repo.Reference(refName, true)
500		if err != nil {
501			return "", false, fmt.Errorf("rotation: failed to read /full/current ref: %w", err)
502		}
503	
504		archiveNumber, err := s.NextGenerationNumber()
505		if err != nil {
506			return "", false, fmt.Errorf("rotation: failed to determine next generation number: %w", err)
507		}
508	
509		// Phase 1: Archive — create ref pointing to the current commit.
510		// If the archive ref already exists, another instance already rotated — skip.
511		archiveRefName := ArchivedGenerationRefName(archiveNumber)
512		if _, refErr := s.repo.Reference(archiveRefName, true); refErr == nil {
513			logging.Info(ctx, "rotation: archive ref already exists, skipping",
514				slog.String("archive_ref", string(archiveRefName)),
515			)
516			return archiveRefName, false, nil
517		}
518		archiveRef := plumbing.NewHashReference(archiveRefName, currentRef.Hash())
519		if err := s.repo.Storer.SetReference(archiveRef); err != nil {
520			return "", false, fmt.Errorf("rotation: failed to create archived ref %s: %w", archiveRefName, err)
521		}
522	
523		// Verify /full/current hasn't been advanced by another writer since we read it.
524		// If it changed, abort — the archive ref is harmless (points to a valid commit)
525		// and the next writer will trigger rotation again.
526		postArchiveRef, err := s.repo.Reference(refName, true)
527		if err != nil {
528			return "", false, fmt.Errorf("rotation: failed to re-read /full/current: %w", err)
529		}
530		if postArchiveRef.Hash() != currentRef.Hash() {
531			logging.Info(ctx, "rotation: /full/current changed during rotation, aborting reset")
532			return archiveRefName, false, nil
533		}
534	
535		// Write generation.json to the current tree before archiving.
536		gen := s.computeGenerationTimestamps(currentTreeHash)
537		archiveTreeHash, err := s.AddGenerationJSONToTree(currentTreeHash, gen)
538		if err != nil {
539			return "", false, fmt.Errorf("rotation: failed to add generation.json: %w", err)
540		}
541	
542		authorName, authorEmail := GetGitAuthorFromRepo(s.repo)
543		archiveCommitHash, err := CreateCommit(ctx, s.repo, archiveTreeHash, currentRef.Hash(), "Archive generation", authorName, authorEmail)
544		if err != nil {
545			return "", false, fmt.Errorf("rotation: failed to create archive commit: %w", err)
546		}
547	
548		// Update the archive ref to point to the commit with generation.json
549		archiveRef = plumbing.NewHashReference(archiveRefName, archiveCommitHash)
550		if err := s.repo.Storer.SetReference(archiveRef); err != nil {
551			return "", false, fmt.Errorf("rotation: failed to update archived ref %s: %w", archiveRefName, err)
552		}
553	
554		// Phase 2: Create fresh orphan /full/current (empty tree, no generation.json)
555		emptyTreeHash, err := BuildTreeFromEntries(ctx, s.repo, make(map[string]object.TreeEntry))
556		if err != nil {
557			return "", false, fmt.Errorf("rotation: failed to build empty tree: %w", err)
558		}
559	
560		orphanCommitHash, err := CreateCommit(ctx, s.repo, emptyTreeHash, plumbing.ZeroHash, "Start generation", authorName, authorEmail)
561		if err != nil {
562			return "", false, fmt.Errorf("rotation: failed to create orphan commit: %w", err)
563		}
564	
565		reset, err := s.resetFullCurrentRefIfUnchanged(ctx, refName, postArchiveRef, orphanCommitHash)
566		if err != nil {
567			return "", false, err
568		}
569		if !reset {
570			return archiveRefName, false, nil
571		}
572	
573		if err := s.AppendPendingFullGenerationPublication(ctx, PendingV2FullGenerationPublication{
574			ArchiveRefName:           archiveRefName.String(),
575			ArchiveCommitHash:        archiveCommitHash.String(),
576			PreviousFullCurrentHash:  currentRef.Hash().String(),
577			ResetFullCurrentRootHash: orphanCommitHash.String(),
578			QueuedAt:                 time.Now().UTC(),
579		}); err != nil {
580			logging.Warn(ctx, "rotation: failed to record pending full rotation; continuing with rotated refs",
581				"error", err,
582				slog.String("archive_ref", string(archiveRefName)),
583				slog.String("previous_full_current_hash", currentRef.Hash().String()),
584				slog.String("archive_commit_hash", archiveCommitHash.String()),
585				slog.String("reset_full_current_root_hash", orphanCommitHash.String()),
586			)
587		}
588	
589		logging.Info(ctx, "generation rotation complete",
590			slog.Int("archived_generation", archiveNumber),
591			slog.String("archive_ref", string(archiveRefName)),
592		)
593	
594		return archiveRefName, true, nil
595	}
596	
597	func (s *V2GitStore) resetFullCurrentRefIfUnchanged(ctx context.Context, refName plumbing.ReferenceName, expectedRef *plumbing.Reference, newHash plumbing.Hash) (bool, error) {
598		newRef := plumbing.NewHashReference(refName, newHash)
599		if err := s.repo.Storer.CheckAndSetReference(newRef, expectedRef); err != nil {
600			if errors.Is(err, storage.ErrReferenceHasChanged) {
601				logging.Info(ctx, "rotation: /full/current changed before reset, leaving current ref intact")
602				return false, nil
603			}
604			return false, fmt.Errorf("rotation: failed to reset /full/current: %w", err)
605		}
606		return true, nil
607	}
608	
609	func (s *V2GitStore) rotateGeneration(ctx context.Context) error {
610		_, _, err := s.RotateCurrentGenerationIfNeeded(ctx, s.maxCheckpoints())
611		return err
612	}
